export interface ExamText {
  id: string;
  title: string;
  body: string;
  source: string;
}

export interface PastQuestion {
  n: number;
  subject: SubjectId;
  topic: string;
  area: Exclude<Area, 'outros'>;
  textId?: string;
  statement: string;
  options: string[];
  answer: number;
  /** Depende de figura que só existe no PDF original. */
  figure?: string;
}

export interface PastExam {
  id: string;
  title: string;
  short: string;
  year: number;
  cargo: string;
  orgao: string;
  applied: string;
  pdf: string;
  gabarito: string;
  why: string;
  /** Mesma estrutura da prova de 2026 (15 básicos, 15 gerais, 40 específicos)? */
  sameStructure: boolean;
  omitted?: string;
  essay?: { title: string; prompt: string };
  texts: ExamText[];
  questions: PastQuestion[];
}

const LETTER = { A: 0, B: 1, C: 2, D: 3, E: 4 } as const;
type L = keyof typeof LETTER;

const pq = (
  n: number,
  area: PastQuestion['area'],
  subject: SubjectId,
  topic: string,
  statement: string,
  options: string[],
  answer: L,
  extra: Partial<Pick<PastQuestion, 'textId' | 'figure'>> = {},
): PastQuestion => ({ n, area, subject, topic, statement, options, answer: LETTER[answer], ...extra });

